<?php
declare(strict_types=1);
namespace App\Validation;
final class ExpenseValidator {public static function validate(array $input):array {$allowed=['description','amount'];if(array_diff(array_keys($input),$allowed))return[null,['form'=>'Unexpected fields were provided.']];$description=trim((string)($input['description']??''));$amount=(string)($input['amount']??'');$errors=[];if($description==='')$errors['description']='Enter an expense name.';elseif(mb_strlen($description)>120)$errors['description']='Use 120 characters or fewer.';elseif(preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u',$description))$errors['description']='The expense name contains invalid characters.';if(!preg_match('/^\d+(?:\.\d{1,2})?$/',$amount))$errors['amount']='Enter a valid amount with up to 2 decimals.';else{[$whole,$decimal]=array_pad(explode('.',$amount,2),2,'');$centimes=((int)$whole*100)+(int)str_pad($decimal,2,'0');if($centimes<1)$errors['amount']='Amount must be at least 0.01 DH.';elseif($centimes>10000000)$errors['amount']='Amount cannot exceed 100,000 DH.';}return$errors?[null,$errors]:[['description'=>$description,'amountCentimes'=>$centimes],[]];}}
